def game_html():
    return gzip.decompress(base64.b85decode(_PAYLOAD)).decode("utf-8")

def main():
    if "--export-html" in sys.argv:
        from pathlib import Path
        Path("whiteout.html").write_text(game_html(), encoding="utf-8")
        print("Saved whiteout.html")
        return
    in_streamlit = False
    try:
        from streamlit.runtime.scriptrunner import get_script_run_ctx
        in_streamlit = get_script_run_ctx(suppress_warning=True) is not None
    except ImportError:
        pass
    if in_streamlit:
        import streamlit as st
        import streamlit.components.v1 as components
        st.set_page_config(page_title="백야 · 설원 생존", page_icon="❄️", layout="wide", initial_sidebar_state="collapsed")
        st.markdown("""<style>
html,body,[data-testid="stAppViewContainer"],[data-testid="stApp"]{margin:0!important;padding:0!important;height:100dvh!important;overflow:hidden!important}
header[data-testid="stHeader"],[data-testid="stToolbar"],[data-testid="stDecoration"],#MainMenu,footer{display:none!important}
.block-container,[data-testid="stMainBlockContainer"]{padding:0!important;max-width:100%!important;margin:0!important}
[data-testid="stElementContainer"]:has(iframe),.element-container:has(iframe){position:fixed!important;inset:0!important;width:100vw!important;height:100vh!important;height:100dvh!important;margin:0!important;z-index:10}
iframe{display:block!important;position:fixed!important;inset:0!important;width:100vw!important;height:100vh!important;height:100dvh!important;max-width:none!important;border:0!important;margin:0!important}
</style>""", unsafe_allow_html=True)
        components.html(game_html(), height=780, scrolling=False)
    else:
        from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
        import os
        page = game_html().encode("utf-8")
        class Handler(BaseHTTPRequestHandler):
            def do_GET(self):
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Content-Length", str(len(page)))
                self.end_headers()
                self.wfile.write(page)
        port = int(os.environ.get("PORT", "8000"))
        print(f"백야 실행 중: http://localhost:{port} (종료: Ctrl+C)")
        try:
            ThreadingHTTPServer(("0.0.0.0", port), Handler).serve_forever()
        except KeyboardInterrupt:
            pass

if __name__ == "__main__":
    main()
